def choose_move(observation):
    def g(obj, key, default=None):
        try:
            return obj.get(key, default)
        except Exception:
            return default

    def as_list(v):
        if v is None:
            return []
        if isinstance(v, list):
            return v
        if isinstance(v, tuple):
            return list(v)
        if isinstance(v, dict):
            return list(v.values())
        return [v]

    def pos_from(x):
        if isinstance(x, dict):
            if "position" in x and isinstance(x["position"], (list, tuple)) and len(x["position"]) >= 2:
                return [x["position"][0], x["position"][1]]
            if "pos" in x and isinstance(x["pos"], (list, tuple)) and len(x["pos"]) >= 2:
                return [x["pos"][0], x["pos"][1]]
            if "x" in x and "y" in x:
                return [x["x"], x["y"]]
        if isinstance(x, (list, tuple)) and len(x) >= 2 and isinstance(x[0], (int, float)) and isinstance(x[1], (int, float)):
            return [x[0], x[1]]
        return None

    def extract_points(v):
        pts = []
        for item in as_list(v):
            p = pos_from(item)
            if p is not None:
                pts.append(p)
            elif isinstance(item, dict):
                for kk in ("cells", "positions", "tiles", "points", "members"):
                    for sub in as_list(g(item, kk)):
                        p2 = pos_from(sub)
                        if p2 is not None:
                            pts.append(p2)
        return pts

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def cheb(a, b):
        dx = abs(a[0] - b[0])
        dy = abs(a[1] - b[1])
        return dx if dx > dy else dy

    def sign(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def clamp1(v):
        return -1 if v < -1 else (1 if v > 1 else int(v))

    obs = observation if isinstance(observation, dict) else {}

    me = pos_from(g(obs, "self")) or pos_from(g(obs, "agent")) or pos_from(g(obs, "position")) or pos_from(g(obs, "pos"))
    if me is None:
        agents = as_list(g(obs, "agents"))
        my_id = g(obs, "agent_id", g(obs, "id"))
        for a in agents:
            if isinstance(a, dict) and (my_id is None or g(a, "id") == my_id or g(a, "agent_id") == my_id):
                me = pos_from(a)
                if me is None:
                    me = pos_from(g(a, "position")) or pos_from(g(a, "pos"))
                if me is not None:
                    break
    if me is None:
        w = g(obs, "width", 0) or 0
        h = g(obs, "height", 0) or 0
        me = [w // 2, h // 2]

    resources = []
    for k in ("resources", "resource_positions", "food", "items", "collectibles", "nodes"):
        resources.extend(extract_points(g(obs, k)))

    enemies = []
    for k in ("enemies", "opponents", "enemy_positions", "enemy_agents", "others"):
        enemies.extend(extract_points(g(obs, k)))
    agents = as_list(g(obs, "agents"))
    my_id = g(obs, "agent_id", g(obs, "id"))
    for a in agents:
        if isinstance(a, dict) and (my_id is None or g(a, "id") != my_id and g(a, "agent_id") != my_id):
            p = pos_from(a)
            if p is None:
                p = pos_from(g(a, "position")) or pos_from(g(a, "pos"))
            if p is not None:
                enemies.append(p)

    goals = []
    for k in ("goals", "targets", "objectives", "capture_points", "frontier", "frontiers", "territory_targets"):
        goals.extend(extract_points(g(obs, k)))

    width = g(obs, "width", None)
    height = g(obs, "height", None)
    if width is None or height is None:
        size = g(obs, "size", None) or g(obs, "map_size", None) or g(obs, "grid_size", None)
        if isinstance(size, (list, tuple)) and len(size) >= 2:
            width, height = size[0], size[1]
    if width is None:
        width = (max([p[0] for p in resources + enemies + goals + [me]] + [0]) + 1) if (resources or enemies or goals) else 0
    if height is None:
        height = (max([p[1] for p in resources + enemies + goals + [me]] + [0]) + 1) if (resources or enemies or goals) else 0

    # Candidate moves
    moves = [[dx, dy] for dx in (-1, 0, 1) for dy in (-1, 0, 1)]

    # Determine pressure from nearby enemies
    nearest_enemy = None
    ne_d = 10**9
    for e in enemies:
        d = cheb(me, e)
        if d < ne_d:
            ne_d = d
            nearest_enemy = e

    nearest_res = None
    nr_d = 10**9
    for r in resources:
        d = manhattan(me, r)
        if d < nr_d:
            nr_d = d
            nearest_res = r

    nearest_goal = None
    ng_d = 10**9
    for t in goals:
        d = manhattan(me, t)
        if d < ng_d:
            ng_d = d
            nearest_goal = t

    # Default target selection
    if nearest_enemy is not None and ne_d <= 2:
        target_mode = "flee"
    elif nearest_res is not None:
        target_mode = "resource"
    elif nearest_goal is not None:
        target_mode = "goal"
    elif nearest_enemy is not None:
        target_mode = "hunt"
    else:
        target_mode = "wander"

    best = [0, 0]
    best_score = None

    for dx, dy in moves:
        nx = me[0] + dx
        ny = me[1] + dy

        score = 0

        # Soft bounds if known
        if width:
            if nx < 0 or nx >= width:
                score -= 5
        if height:
            if ny < 0 or ny >= height:
                score -= 5

        # Enemy avoidance / pursuit
        if enemies:
            dmin = None
            for e in enemies:
                d = cheb([nx, ny], e)
                if dmin is None or d < dmin:
                    dmin = d
            if dmin is not None:
                if target_mode == "flee":
                    score += dmin * 10
                else:
                    score += dmin * 2

        # Resource / goal attraction
        if nearest_res is not None:
            score += (20 - manhattan([nx, ny], nearest_res)) * (3 if target_mode == "resource" else 1)
        if nearest_goal is not None:
            score += (20 - manhattan([nx, ny], nearest_goal)) * (2 if target_mode == "goal" else 1)

        # Gentle center-seeking when nothing else
        if target_mode == "wander":
            cx = (width - 1) / 2 if width else me[0]
            cy = (height - 1) / 2 if height else me[1]
            score += -abs(nx - cx) - abs(ny - cy)
            score += ((nx + 2 * ny + me[0] + me[1]) % 3) * 0.01

        # Prefer movement over standing still when tied
        if dx != 0 or dy != 0:
            score += 0.1

        if best_score is None or score > best_score or (score == best_score and (dx, dy) < (best[0], best[1])):
            best_score = score
            best = [clamp1(dx), clamp1(dy)]

    return best

